import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Le ipotesi del teorema di Rolle","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/cf/cfea1.md","filePath":"lezioni/c_analisi/cf/cfea1.md"}`),a={name:`lezioni/c_analisi/cf/cfea1.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="le-ipotesi-del-teorema-di-rolle" tabindex="-1">Le ipotesi del teorema di Rolle <a class="header-anchor" href="#le-ipotesi-del-teorema-di-rolle" aria-label="Permalink to “Le ipotesi del teorema di Rolle”">​</a></h1><p>Proviamo a vedere cosa può succedere se manca una delle ipotesi del teorema di Rolle:</p><ol><li>che la funzione sia continua</li><li>che la funzione sia derivabile all&#39;interno dell&#39;intervallo</li><li>che l&#39;intervallo sia chiuso e limitato</li><li>che i valori agli estremi dell&#39;intervallo siano uguali</li></ol><hr><h3 id="caso-della-funzione-non-continua" tabindex="-1">Caso della funzione non continua <a class="header-anchor" href="#caso-della-funzione-non-continua" aria-label="Permalink to “Caso della funzione non continua”">​</a></h3><p>Sono verificate tutte le ipotesi eccetto la prima (le due parti di curva devono avere la stessa inclinazione nel punto di discontinuità). Ho utilizzato una discontinuità di <a href="./../ce/ceba.html">prima specie</a>.</p><hr><h3 id="caso-della-funzione-non-derivabile-all-interno-dell-intervallo" tabindex="-1">Caso della funzione non derivabile all&#39;interno dell&#39;intervallo <a class="header-anchor" href="#caso-della-funzione-non-derivabile-all-interno-dell-intervallo" aria-label="Permalink to “Caso della funzione non derivabile all&#39;interno dell&#39;intervallo”">​</a></h3><p>Questa non è derivabile dove c&#39;è la punta.</p><blockquote><p><strong>Attenzione:</strong> Se la funzione è derivabile all&#39;interno e non è derivabile sul bordo dell&#39;intervallo il teorema vale lo stesso: sapresti fare un <a href="./cfea1a.html">esempio?</a></p></blockquote><hr><p>Se la funzione fosse continua in un intervallo che non fosse chiuso potrei pensare una discontinuità di terza specie ad un estremo ed il teorema non sarebbe più valido (ho esagerato il punto sul bordo destro per renderlo più visibile e mostrare la discontinuità).</p><hr><p>Il quarto esempio è il più semplice: se i valori non fossero uguali una semplice retta mi mostrerebbe che il teorema non è più valido.</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};